z : Fin (P.n - 1) → ℝ
reducedHess : (Fin (P.n - 1) → ℝ) → (Fin (P.n - 1) → ℝ) →ₗ[ℝ] Fin (P.n - 1) → ℝ
reducedGrad : (Fin (P.n - 1) → ℝ) → Fin (P.n - 1) → ℝ
reducedHessInv : (Fin (P.n - 1) → ℝ) →ₗ[ℝ] Fin (P.n - 1) → ℝ
h_hess :
  reducedHess z =
    Matrix.toLin'
      (let D := Matrix.diagonal fun i => deriv (deriv (P.f ⟨↑i, ⋯⟩)) (z i);
      let d := deriv (deriv (P.f ⟨P.n - 1, ⋯⟩)) (1 - ∑ j, z j);
      D + d • Matrix.vecMulVec (fun x => 1) fun x => 1)
h_left : reducedHessInv ∘ₗ reducedHess z = LinearMap.id
h_right : reducedHess z ∘ₗ reducedHessInv = LinearMap.id
⊢ let D := Matrix.diagonal fun i => deriv (deriv (P.f ⟨↑i, ⋯⟩)) (z i);
  let d := deriv (deriv (P.f ⟨P.n - 1, ⋯⟩)) (1 - ∑ j, z j);
  let g := reducedGrad z;
  let reducedHessMatrix := D + d • Matrix.vecMulVec (fun x => 1) fun x => 1;
  let δz := -reducedHessInv (reducedGrad z);
  D.IsDiag ∧
    isRankOneModification D reducedHessMatrix ∧ (reducedHessMatrix *ᵥ δz = fun i => -g i) ∧ ∃ C, P.n - 1 ≤ C * P.n + C

